/// <summary>
/// update field values to record after mapping to the entity.
/// </summary>
/// <param name="_sender"><c>InventInventoryCountingJournalLineEntity</c> raising the event.</param>
/// <param name="_eventArgs">The arguments of this event.</param>
[DataEventHandler(tableStr(InventInventoryCountingJournalLineEntity), DataEventType::MappedEntityToDataSource)]
public static void InventInventoryCountingJournalLineEntity_onMappedEntityToDataSource(Common _sender, DataEventArgs _eventArgs)
{
    DataEntityContextEventArgs contextEventArgs = _eventArgs as DataEntityContextEventArgs;
    DataEntityRuntimeContext entityCtx = contextEventArgs.parmEntityContext();
    DataEntityDataSourceRuntimeContext dataSourceCtx = contextEventArgs.parmEntityDataSourceContext();

    if ((entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert || entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
        && dataSourceCtx.name() == dataEntityDataSourceStr(InventInventoryCountingJournalLineEntity, InventJournalTrans))
    {
        Info('Bug 400277 troubleshoot ==> 1');
        InventInventoryCountingJournalLineEntity inventInventoryCountingJournalEntry = _sender as InventInventoryCountingJournalLineEntity;
        InventJournalTrans  inventJournalTrans = dataSourceCtx.getBuffer();
        InventJournalTable  inventJournalTable;
        Qty                 origQty;
        InventTable         inventTable = InventTable::find(inventJournalTrans.ItemId);
        InventDim           transInventDim = InventDim::find(inventJournalTrans.InventDimId);

        InventMov_Journal   inventMovement;
        InventDimParm       inventDimParm;

        select firstonly JournalNameId, METJournalLinesCount from inventJournalTable
            where inventJournalTable.JournalId == inventInventoryCountingJournalEntry.JournalNumber;

        if (_sender.InventInventoryDimensionEntityFieldsMapping::isAnyInventDimFieldSet())
        {
            Info('Bug 400277 troubleshoot ==> 2');
            InventDim inventDim = inventJournalTrans.inventDim();
            _sender.InventInventoryDimensionEntityFieldsMapping::updateInventDim(inventDim);
            inventJournalTrans.InventDimId = InventDim::findOrCreate(inventDim).inventDimId;

            inventDimParm.initFromInventDim(inventDim);
            inventJournalTrans.InventOnHand = InventOnHandQty::newParameters(inventJournalTrans.ItemId, inventDim, inventDimParm).physicalInvent();
            Info('Bug 400277 troubleshoot ==> 3');
        }

        if (inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity)
        {
            Info('Bug 400277 troubleshoot ==> 4');
            //CWQty
            origQty = inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity;
            inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity = METJournalUnitConversion::construct().getConvertedCWQtyForItem(InventLocation::find(inventInventoryCountingJournalEntry.WarehouseId),inventInventoryCountingJournalEntry.ItemNumber, inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity);
            inventJournalTrans.PdsCWQty = inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity;
            inventJournalTrans.modifiedField(fieldNum(InventJournalTrans, PdsCWQty));
            inventJournalTrans.PdsCWInventQtyCounted = inventJournalTrans.PdsCWInventOnHand + inventJournalTrans.PdsCWQty;
            Info(strFmt("%1,%2",inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity, inventInventoryCountingJournalEntry.AdjustmentQuantity));
            Info('Bug 400277 troubleshoot ==> 5');
            //Qty
            if (InventJournalName::find(inventJournalTable.JournalNameId).METExternalWMSUOM && inventJournalTable.METJournalLinesCount)
            {
                Info('Bug 400277 troubleshoot ==> 6');
                Info(strFmt("%1,%2",inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity, inventInventoryCountingJournalEntry.AdjustmentQuantity));
                inventInventoryCountingJournalEntry.AdjustmentQuantity = METJournalUnitConversion::construct().getConvertedQtyCWQtyForItem(InventLocation::find(inventInventoryCountingJournalEntry.WarehouseId),inventInventoryCountingJournalEntry.ItemNumber, origQty, NoYes::Yes);
            }

            // Added the Qty assingement, if value is available in file else it making it as null
            if (inventInventoryCountingJournalEntry.AdjustmentQuantity != 0)
            {
                Info('Bug 400277 troubleshoot ==> 7');
                Info(strFmt("%1,%2",inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity, inventInventoryCountingJournalEntry.AdjustmentQuantity));
                inventJournalTrans.Qty = inventInventoryCountingJournalEntry.AdjustmentQuantity;
                inventJournalTrans.Counted =  inventJournalTrans.InventOnHand + inventJournalTrans.Qty;
            }
        }
        else
        {
            Info('Bug 400277 troubleshoot ==> 8');
            Info(strFmt("%1,%2",inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity, inventInventoryCountingJournalEntry.AdjustmentQuantity));
            if (InventJournalName::find(inventJournalTable.JournalNameId).METExternalWMSUOM && inventJournalTable.METJournalLinesCount)
            {
                Info('Bug 400277 troubleshoot ==> 9');
                Info(strFmt("%1,%2",inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity, inventInventoryCountingJournalEntry.AdjustmentQuantity));
                inventInventoryCountingJournalEntry.AdjustmentQuantity = METJournalUnitConversion::construct().getConvertedQtyCWQtyForItem(InventLocation::find(inventInventoryCountingJournalEntry.WarehouseId),inventInventoryCountingJournalEntry.ItemNumber, inventInventoryCountingJournalEntry.AdjustmentQuantity);
            }

            // Added the Qty assingement, if value is available in file else it making it as null
            if (inventInventoryCountingJournalEntry.AdjustmentQuantity != 0)
            {
                Info('Bug 400277 troubleshoot ==> 10');
                inventJournalTrans.Qty = inventInventoryCountingJournalEntry.AdjustmentQuantity;
                inventJournalTrans.Counted =  inventJournalTrans.InventOnHand + inventJournalTrans.Qty;
                Info(strFmt("%1,%2",inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity, inventInventoryCountingJournalEntry.AdjustmentQuantity));
            }
            else
            {
                Info('Bug 400277 troubleshoot ==> 11');
                inventJournalTrans.Counted =  inventJournalTrans.InventOnHand;
                Info(strFmt("%1,%2",inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity, inventInventoryCountingJournalEntry.AdjustmentQuantity));
            }
        }

        if(inventInventoryCountingJournalEntry.METIsSDSI == NoYes::Yes)
        {
            Info(strFmt("%1,%2",inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity, inventInventoryCountingJournalEntry.AdjustmentQuantity));
            Info('Bug 400277 troubleshoot ==> 12');
            if(inventJournalTrans.Counted < inventJournalTrans.InventOnHand
                || inventJournalTrans.PdsCWInventQtyCounted < inventJournalTrans.PdsCWInventOnHand)
            {
                Info('Bug 400277 troubleshoot ==> 13');
                InventJournalTrans.CountingReasonCode = "SD";
                Info(strFmt("%1,%2",inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity, inventInventoryCountingJournalEntry.AdjustmentQuantity));
            }
            else
            {
                Info(strFmt("%1,%2",inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity, inventInventoryCountingJournalEntry.AdjustmentQuantity));
                Info('Bug 400277 troubleshoot ==> 14');
                InventJournalTrans.CountingReasonCode = "SI";
            }
        }

        Info(strFmt("%1,%2",inventInventoryCountingJournalEntry.AdjustmentCatchWeightQuantity, inventInventoryCountingJournalEntry.AdjustmentQuantity));
        Info('Bug 400277 troubleshoot ==> 15');
        inventJournalTrans.DefaultDimension = InventSite::changeDimension(inventTable.DefaultDimension, InventSite::find(transInventDim.InventSiteId).SiteId);

        inventJournalTrans.inventMovement().journalSetCounted();
        Info('Bug 400277 troubleshoot ==> 16');
    }
}
